select 'KE',yg.year_group_code,'KE_MATH','Mathematics',
'[{"name":"Senior Secondary Mathematics","topics":[{"name":"Pure Mathematics","subtopics":["Comprehensive algebra and calculus","Trigonometry and coordinate geometry","Series and sequences","Vectors and matrices"]},{"name":"Statistics and Mechanics","subtopics":["Probability distributions","Statistical inference","Kinematics and dynamics","KCSE examination preparation"]}]}]',
'{"by_end_of_year":["Complete all KCSE Mathematics content","Apply mathematical skills to real-world problems","Achieve target grade in KCSE"]}'
from year_group_equivalencies yg
where yg.country_code='KE' and yg.stage='senior_secondary'
on conflict (country_code,year_group_code,subject_code) do nothing;

